/*
 * A337037  Numbers whose every unordered factorization has a distinct sum of
 *          factors.
 * https://oeis.org/A337037
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 75, u16 n <= 75, u32 n <= 75, u64 n <= 75, u128 n <= 75,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A337037: Numbers whose every unordered factorization has a distinct sum of factors. */
/* The sequence is generated by testing each integer for the unique-sum property. */
/* The algorithm uses the following observations:                      */
/*   1. any bad number m is a divisor of all bad numbers.               */
/*   2. every new bad number is added to a list of primitive bads.      */
/*   3. for a number n not divisible by a known bad, we enumerate all    */
/*      unordered factorizations and check whether all factor-sums are   */
/*      distinct.  If a duplicate sum is found, n is bad.                */
/*   4. good numbers are collected in order until the requested index.  */
/* The implementation is fully self‑contained and uses only the allowed   */
/* features and helper functions.                                         */
 
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ------------------------------------------------------------------ */
/*  Dynamic arrays for good and bad numbers                            */
/* ------------------------------------------------------------------ */
static seq_t *good = NULL;
static size_t good_len = 0, good_cap = 0;
static uint64_t *bads = NULL;
static size_t bad_len = 0, bad_cap = 0;
static idx_t lastChecked = 0;          /* last integer examined            */
static bool initialized = false;       /* lazy initialization flag        */

/* ------------------------------------------------------------------ */
/*  Helper: ensure enough space for an array of seq_t                  */
/* ------------------------------------------------------------------ */
static void ensure_good(void) {
    if (good_len >= good_cap) {
        size_t newCap = good_cap == 0 ? 8 : good_cap * 2;
        seq_t *p = (seq_t*)realloc(good, newCap * sizeof(seq_t));
        if (!p) exit(EXIT_FAILURE);
        good = p; good_cap = newCap;
    }
}

static void ensure_bad(void) {
    if (bad_len >= bad_cap) {
        size_t newCap = bad_cap == 0 ? 8 : bad_cap * 2;
        uint64_t *p = (uint64_t*)realloc(bads, newCap * sizeof(uint64_t));
        if (!p) exit(EXIT_FAILURE);
        bads = p; bad_cap = newCap;
    }
}

/* ------------------------------------------------------------------ */
/*  Duplicate‑sum detection:                                            */
/*  A small fixed array of sums is used because the number of            */
/*  distinct factorizations for any integer encountered here is         */
/*  well below a few thousand (far below 4096).                        */
/* ------------------------------------------------------------------ */
#define MAX_SUMS 4096
static seq_t seenSums[MAX_SUMS];
static size_t seenCnt;

/* record a sum; return true iff it was not seen before */
static bool recordSum(seq_t s) {
    for (size_t i = 0; i < seenCnt; ++i)
        if (seenSums[i] == s) return false;
    if (seenCnt < MAX_SUMS) seenSums[seenCnt++] = s;
    return true;
}

/* ------------------------------------------------------------------ */
/*  Recursively generate unordered factorizations of 'rem'.            */
/*  'minf' keeps the factors non‑decreasing to avoid duplicates.      */
/*  'sum' accumulates the sum of already chosen factors.               */
/* ------------------------------------------------------------------ */
static bool gen_factors(uint64_t rem, uint64_t minf, seq_t sum) {
    /* factorization that consists of the factors chosen so far
       plus the remaining product 'rem' */
    if (!recordSum(sum + (seq_t)rem)) return false;

    for (uint64_t f = minf; f <= rem / f; ++f) {
        if (rem % f == 0) {
            if (!gen_factors(rem / f, f, sum + f))
                return false;
        }
    }
    return true;
}

/* ------------------------------------------------------------------ */
/*  Test if a given integer is good (all sums distinct).               */
/*  It is assumed that 'bad_count' numbers in 'bad_lst' are known to  */
/*  divide all bad integers; hence, if x % bad == 0, it is immediately  */
/*  declared bad.  Otherwise, all unordered factorizations are examined */
/*  for duplicate sums.                                                */
/* ------------------------------------------------------------------ */
static bool is_good(uint64_t x) {
    if (x == 1) return true;          /* 1 is in the sequence by convention */

    /* Check divisibility by already discovered bad primes/divisors. */
    for (size_t i = 0; i < bad_len; ++i)
        if (x % bads[i] == 0) return false;

    /* Enumerate factorizations and check sums. */
    seenCnt = 0;
    return gen_factors(x, 2, 0);
}

/* ------------------------------------------------------------------ */
/*  Main function required by the build.                               */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n) {
    /* One‑time initialization of the list of primitive bad numbers. */
    if (!initialized) {
        bad_cap = 8;
        bads = (uint64_t*)malloc(bad_cap * sizeof(uint64_t));
        if (!bads) exit(EXIT_FAILURE);
        bads[0] = 4;          /* 4 is the first bad number. */
        bad_len = 1;
        initialized = true;
    }

    /* Generate good numbers until we have at least n of them. */
    while (good_len < (size_t)n) {
        ++lastChecked;          /* candidate integer to test */

        if (is_good((uint64_t)lastChecked)) {
            /* store good number */
            ensure_good();
            good[good_len++] = (seq_t)lastChecked;
        } else {
            /* new primitive bad number (not divisible by existing bads) */
            ensure_bad();
            bads[bad_len++] = (uint64_t)lastChecked;
        }
    }

    /* Return the n-th element (1‑based). */
    return good[n - 1];
}
